package com.lumen.money;
import java.math.BigDecimal;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class LedgerAmountTest {
 @Test void respectsCurrencyScaleAndHalfUpTies() {
  assertEquals(1005L, LedgerAmount.minorUnits(new BigDecimal("1.005"),"KWD"));
  assertEquals(1L, LedgerAmount.minorUnits(new BigDecimal("1.4"),"JPY"));
  assertEquals(2L, LedgerAmount.minorUnits(new BigDecimal("1.5"),"JPY"));
  assertEquals(101L, LedgerAmount.minorUnits(new BigDecimal("1.005"),"USD"));
  assertEquals(101L, LedgerAmount.minorUnits(new BigDecimal("1.005"),"EUR"));
  assertEquals(0L, LedgerAmount.minorUnits(BigDecimal.ZERO,"KWD"));
 }
 @Test void preservesLongBoundaryAndRejectsOverflowAndInvalidInputs() {
  assertEquals(Long.MAX_VALUE,LedgerAmount.minorUnits(new BigDecimal("92233720368547758.07"),"USD"));
  assertEquals(Long.MAX_VALUE,LedgerAmount.minorUnits(new BigDecimal("9223372036854775.807"),"KWD"));
  assertThrows(ArithmeticException.class,()->LedgerAmount.minorUnits(new BigDecimal("92233720368547758.075"),"USD"));
  assertThrows(IllegalArgumentException.class,()->LedgerAmount.minorUnits(new BigDecimal("-0.001"),"KWD"));
  assertThrows(IllegalArgumentException.class,()->LedgerAmount.minorUnits(BigDecimal.ONE,"XXX"));
  assertThrows(IllegalArgumentException.class,()->LedgerAmount.minorUnits(null,"EUR"));
 }
}
